import React, { useState } from "react";
import { BrowserRouter as Router, Routes, Route, useNavigate } from "react-router-dom";
import Login from "./Login";
import AdminDashboard from "./AdminDashboard";
import UserShop from "./components/UserShop";
import CartPage from "./components/CartPage";
import CheckoutPage from "./components/CheckoutPage";
import OrderSuccess from "./components/OrderSuccess";

function App() {
  const [role, setRole] = useState(null);
  const [token, setToken] = useState(null);
  const [message, setMessage] = useState("");
  const [showLogin, setShowLogin] = useState(false);
  const [showRegister, setShowRegister] = useState(false);

  const handleLogin = (username, password, type) => {
    if (type === "admin" && username === "admin" && password === "pass") {
      setRole("admin");
      setToken("admin_token");
      setMessage("✅ Admin login successful!");
      setShowLogin(false);
    } else if (type === "user") {
      setRole("user");
      setToken("user_token");
      setMessage(`👤 Welcome, ${username}!`);
      setShowLogin(false);
    } else {
      setMessage("❌ Invalid credentials");
    }
  };

  const handleLogout = () => {
    setRole(null);
    setToken(null);
    setMessage("You have logged out.");
  };

  return (
    <Router>
      <div className="min-h-screen bg-gray-50 font-sans pt-8">
        {/* Navbar */}
        <nav className="flex justify-between px-6 py-4 bg-gray-900 text-white fixed top-0 w-full shadow-md">
          <h1 className="text-2xl font-bold">💊 MediShop</h1>
          <div className="space-x-4">
            {!role && (
              <>
                <button
                  onClick={() => {
                    setShowLogin(true);
                    setShowRegister(false);
                  }}
                  className="hover:text-indigo-400"
                >
                  Login
                </button>
                <button
                  onClick={() => {
                    setShowRegister(true);
                    setShowLogin(false);
                  }}
                  className="hover:text-indigo-400"
                >
                  Register
                </button>
              </>
            )}
            {role && (
              <button onClick={handleLogout} className="hover:text-red-400">
                Logout
              </button>
            )}
          </div>
        </nav>

        <div className="pt-24">
          {message && (
            <div className="bg-indigo-100 text-indigo-800 p-2 text-center mb-4 rounded">
              {message}
            </div>
          )}

          {/* --- LOGIN PAGE --- */}
          {showLogin && !role && (
            <Login onLogin={handleLogin} message={{ type: "", text: message }} />
          )}

          {/* --- REGISTER PAGE --- */}
          {showRegister && !role && (
            <div className="flex justify-center items-center h-[80vh] text-gray-700 text-lg">
              Registration page under development...
            </div>
          )}

          {/* --- HOME PAGE --- */}
          {!showLogin && !showRegister && !role && (
            <div className="flex justify-center items-center h-[80vh] text-2xl text-gray-700">
              Welcome to 💊 MediShop – Your Online Medicine Store
            </div>
          )}

          {/* --- AFTER LOGIN --- */}
          {role === "admin" && (
            <AdminDashboard
              token={token}
              onLogout={handleLogout}
              setMessage={setMessage}
            />
          )}

          {role === "user" && (
            <Routes>
              <Route
                path="/"
                element={
                  <UserShop
                    token={token}
                    onLogout={handleLogout}
                    setMessage={setMessage}
                  />
                }
              />
              <Route path="/cart" element={<CartPage />} />
              <Route path="/checkout" element={<CheckoutPage />} />
              <Route path="/success" element={<OrderSuccess />} />
            </Routes>
          )}
        </div>
      </div>
    </Router>
  );
}

export default App;
